import math
def control(obs):
    h = obs.get('hitch_deg', 0.0)
    cam = obs.get('views', {}).get('camera', {}) or {}
    walls = cam.get('walls', [])
    right = []
    left = []
    for p in walls:
        try:
            b, d = float(p[0]), float(p[1])
        except (TypeError, ValueError, IndexError):
            continue
        lateral = d * math.sin(math.radians(b))
        if abs(lateral) < 0.15:
            continue
        if lateral < 0:
            right.append(abs(lateral))
        else:
            left.append(abs(lateral))
    # Steer to move the trailer rear away from the closer side.
    steer = 1.5 * h
    if right and left:
        steer += max(-9.0, min(9.0, 5.0 * (min(left) - min(right))))
    steer = max(-14.0, min(14.0, steer))
    return (steer, -0.16, -23.0)

